// Precise rethrow (Java 7+): khai báo hẹp hơn kiểu bắt
void run() throws IOException, SQLException {
    try {
        process();                 // chỉ ném IOException hoặc SQLException
    } catch (Exception e) {        // e effectively final
        log.error("failed", e);
        throw e;                   // compiler suy ra đúng 2 kiểu trên
    }
}

