// ĐÚNG: JMH
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations = 5, time = 1)
@Measurement(iterations = 10, time = 1)
@Fork(2)
@State(Scope.Benchmark)
public class LogBenchmark {

    private double x;                    // không phải hằng -> chặn constant folding

    @Setup
    public void setup() { x = ThreadLocalRandom.current().nextDouble(1, 100); }

    @Benchmark
    public double measure() {
        return Math.log(x);              // trả về giá trị -> JMH tự nuốt, chặn DCE
    }

    @Benchmark
    public void measureWithBlackhole(Blackhole bh) {
        bh.consume(Math.log(x));         // cách khác khi có nhiều kết quả
    }
}

// Bất biến đúng: defensive copy cả hai đầu
public final class Order {
    private final String id;
    private final List<Item> items;

    public Order(String id, List<Item> items) {
        this.id = Objects.requireNonNull(id, "id");           // fail fast
        this.items = List.copyOf(items);                      // copy khi nhan (List.copyOf: Java 10+)
        // Java 8: this.items = Collections.unmodifiableList(new ArrayList<>(items));
    }

    public List<Item> getItems() { return items; }            // đã unmodifiable
}

// Record: shallow immutable, cần compact constructor để chặt chẽ
public record Shipment(String code, List<Item> items) {
    public Shipment {
        Objects.requireNonNull(code, "code");
        items = List.copyOf(items);      // nếu không, list bên ngoài vẫn sửa được
    }
}

