// Xử lý lỗi tập trung ở biên HTTP
@RestControllerAdvice
class ApiExceptionHandler {

    @ExceptionHandler(InsufficientStockException.class)
    ResponseEntity<ApiError> onStock(InsufficientStockException e) {
        log.warn("insufficient stock sku={}", e.getSku());          // log đủ để điều tra
        return ResponseEntity.status(409)
                .body(new ApiError("OUT_OF_STOCK", "Sản phẩm không đủ tồn kho"));
    }

    @ExceptionHandler(Exception.class)
    ResponseEntity<ApiError> onUnexpected(Exception e) {
        log.error("unhandled error", e);                            // stack trace vào log
        return ResponseEntity.status(500)
                .body(new ApiError("INTERNAL", "Đã có lỗi xảy ra")); // không lộ ra client
    }
}

